javascript:
frappe.query_reports["Production Completion Status"] = {
    filters: [
        {
            fieldname: "date",
            label: "Date",
            fieldtype: "Date"
        },
        {
            fieldname: "department",
            label: "Department",
            fieldtype: "Link",
            options: "Physical Cell"
        },
        {
            fieldname: "buyer",
            label: "Buyer",
            fieldtype: "Link",
            options: "Customer"
        },
        {
            fieldname: "style",
            label: "Style",
            fieldtype: "Link",
            options: "Style Master"
        }
    ],

    formatter: function(value, row, column, data, default_formatter) {
        value = default_formatter(value, row, column, data);

        if (column.fieldname === "completed_percent" && data) {
            let percent = data.completed_percent || 0;

            if (percent < 100) {
                value = `<span style="color:#d32f2f;font-weight:bold">${percent}%</span>`;
            } else {
                value = `<span style="color:#2e7d32;font-weight:bold">${percent}%</span>`;
            }
        }

        return value;
    }
};
